MultiLanguageSpellData['mx'][223844] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]Los augures estrella usaron este aparato de mano para concentrar una inmensa cantidad de Luz estelar hacia una pequeña área concentrada. El aparato se usaba principalmente durante festivales, rituales de adoración de estrellas, o cuando el augur necesitaba tomar algo de un estante alto."}
MultiLanguageSpellData['mx'][223845] = {name = "Rama de Arcan'dor", additional_info = "Alcance de 100 m\nInstante\n[q]Tienes a 1 marchitos encantados.\n\n Entrégalos a Shal'Aran o haz clic derecho para retirarlos.\n\n El efecto se cancela si abandonas Suramar."}
MultiLanguageSpellData['mx'][223846] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]Los príncipes y princesas gobernantes en Suramar eligieron solo usar sus coronas en los eventos más formales. Las mantenían guardadas en las demás ocasiones, ya que se consideraban pasadas de moda."}
MultiLanguageSpellData['mx'][223847] = {name = "Marchito embelesado avanzado", additional_info = nil}
MultiLanguageSpellData['mx'][223848] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]El Fuerte Torre Oscura era mantenido por un pequeño ejército de sirvientes. Uno de esos sirvientes era Kalyndras, quien era responsable de vigilar la armería del Fuerte y el almacén de municiones. Igual que muchos de los sirvientes de Cresta Cuervo, sucumbió ante los demonios durante la Guerra de los Ancestros."}
MultiLanguageSpellData['mx'][223849] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]Este poderosísimo enfoque de hechizo de Altonato fue destrozado en una expedición arqueológica negligente. Sus fragmentos son todo lo que queda."}
MultiLanguageSpellData['mx'][223850] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]Esta llave no abre ninguna puerta. En su lugar, es un gesto ceremonial de invitación a la Academia, como un modo de decir, \"nuestras puertas están abiertas para ti.\""}
MultiLanguageSpellData['mx'][223851] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]Reverenciado por los mineros y herreros, Rethu Cuerno Férreo fue uno de los primeros tauren en asentarse en las Islas Quebradas. Sus descendientes continúan su tradición de metalistería en el Enclave Ferrocorno, cerca de la cima de Altamontaña."}
MultiLanguageSpellData['mx'][223852] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]Los drogbar siempre han sido maestros del arte de la joyería. En particular, el chamán de la tribu usaba pesados collares de tres piedras. Los maestros legaban estos collares a sus pupilos."}
MultiLanguageSpellData['mx'][223853] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]Eche'ro fue la mascota, montura y compañero de batalla de Huln Altamontaña, legendario héroe de la Guerra de los ancestros."}
MultiLanguageSpellData['mx'][223854] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]El ojo de un poderoso demonio, preservado en el frío y pedregoso suelo de Stormheim. Escritos de la época de la Guerra de los Ancestros establecen que Undravius fue un comandante Señor vil con deseo de eliminar todas las formas de vida de Azeroth."}
MultiLanguageSpellData['mx'][223855] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]Bajo la guía de unos ingenieros mo'arg poco cooperativos, los cazadores de demonios pudieron crear muchos de estos portales hacia Mardum. Desafortunadamente, jamás lograron imponerse, ya que normalmente salían más demonios de los que entraban."}
MultiLanguageSpellData['mx'][223856] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]Muchos aventureros negligentes fallecieron al activar uno de estos aparatos sin conocer su función. A menudo no queda claro si su activación invocará a un solo diablillo, o a una legión de señores del foso."}
MultiLanguageSpellData['mx'][223857] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]No es claro por qué cualquier criatura, demoníaca o de Azeroth, elegiría hacer enojar a Mannoroth por guardar un poco de su sangre en un tarro."}
MultiLanguageSpellData['mx'][223858] = {name = "Proyecto de arqueología", additional_info = "Instante\n[q]En su apuro, los draenei trajeron algunos artefactos con ellos al irse de Argus. Este libro es una de esas pocas reliquias que sobrevivieron el viaje hasta hoy en día."}
