MultiLanguageSpellData['mx'][225128] = {name = "Tranquilidad de la Fuente de la Noche", additional_info = "Aproximadamente 3 activaciones por minuto\n[q]Tus hechizos de sanación tienen una probabilidad de concederle al objetivo Tranquilidad de la Fuente de la Noche, y restaura 1342 p. de salud por 12 s. Sanar a un aliado afectado por Tranquilidad de la Fuente de la Noche puede causar que el efecto detone y sane a todos los aliados cercanos por 224 ."}
MultiLanguageSpellData['mx'][225129] = {name = "Triunvirato", additional_info = "Aproximadamente 0.7 activaciones por minuto\n[q]Tus ataques cuerpo a cuerpo y a la distancia tienen una probabilidad de otorgarte encantamientos de fuego, de escarcha o arcano durante 20 s."}
