MultiLanguageSpellData['mx'][225135] = {name = "Golpes recursivos", additional_info = "Aproximadamente 1 activaciones por minuto\n[q]Tus ataques tienen la posibilidad de dar golpes recursivos durante 15 s y por tanto, tus ataques automáticos infligirán 161 p. de daño adicional e incrementará la intensidad de los golpes recursivos."}
