MultiLanguageSpellData['mx'][228264] = {name = "Forma del vacío", additional_info = "[q]Se activa cuando se lanza Erupción del vacío. Altera tu Forma de las sombras con los poderes del Vacío, aumenta un 10% tu daño con hechizos y restablece el tiempo de reutilización de Explosión mental.\n\n Dura 20 s. Lanzar Peste devoradora aumenta la duración de Forma del vacío 2.5 s."}
MultiLanguageSpellData['mx'][228265] = {name = "Corrosión de alma", additional_info = "Rango ilimitado\nInstante\n[q]Cada 3 segundos un jugador permanece dentro del Pozo de Almas, un Fragmento de alma deja el Pozo e inflije 4805 p. de daño de las Sombras en un radio de 5 m del jugador objetivo y los aflige con Corrosión de alma.\n\n Corrosión de alma inflige 790 p. de daño de las Sombras cada segundo durante 3 min. Este efecto se acumula."}
