MultiLanguageSpellData['mx'][239412] = {name = "[q5]Celumbra, la Dicotomía nocturna", additional_info = "Hechizo de 2 seg\nComponentes:\nMadeja de paño de sombras , Madeja de tejido de estrellas , Esencia de fragmento del vacío , Sangre de Sargeras (65), Filoseda imbuida (125), Duendespina punzante , Tripa rúnica\n[q]Fabricar Celumbra, la Dicotomía nocturna\nInstructor de profesión:\nSastrería de Legion (100)\nCosto:\n250\n\n[q5]Celumbra, la Dicotomía nocturna\nSe liga al equiparlo\nÚnico-Equipado: Legendario de Legion (1)Hombro Tela\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 4 p.\n\n[q0]Ranura prismática\n[q0]Ranura prismática\n[q0]Ranura prismática\n\nDurabilidad 120 / 120\nClases: Sacerdote , Mago , Brujo\n[q2]Equipar: Cuando hay un enemigo en un radio de 12 m a tu alrededor, te ocultas en las sombras para reducir el daño recibido un 5% y aumenta tu velocidad de movimiento un 10%. Cuando no hay enemigos en un radio de 12 m a tu alrededor, Luz estelar de Celumbra te sana por un 1% de tu salud máxima durante 1 s.\nNecesitas ser de nivel 40\n[q]\"Sombra y estrella, oscuridad y luz, desesperación y esperanza.\""}
MultiLanguageSpellData['mx'][239413] = {name = "[q5]Refugio eterno de la centinela", additional_info = "Hechizo de 2 seg\nComponentes:\nPellejoanciano tocado por fuego fatuo , Esencia de fragmento del vacío , Sangre de Sargeras (65), Cuero de petrapiel (250)\n[q]Fabricar Refugio eterno de la centinela.\nInstructor de profesión:\nPeletería de Legion (100)\nCosto:\n250\n\n[q5]Refugio eterno de la centinela\nSe liga al equiparlo\nÚnico-Equipado: Legendario de Legion (1)Pies Cuero\n5 armadura\n+4 [Agilidad o Intelecto]+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de maestría + 4 p.\n\n[q0]Ranura prismática\n[q0]Ranura prismática\n[q0]Ranura prismática\n\nDurabilidad 95 / 95\nClases: Pícaro , Monje , Druida , Cazador de Demonios\n[q2]Equipar: Cada vez que matas a un enemigo, obtienes un 5% de aumento de velocidad de movimiento durante 1 min. Este efecto se acumula hasta 5 veces. Al alcanzar 5 acumulaciones, te convertirás en fuego fatuo cuando estés fuera del combate para aumentar tu velocidad de movimiento aún más y obtener la habilidad de volar.\nNecesitas ser de nivel 40\n[q]\"Su espíritu está imbuido en el cuero de estos botines, que la mantienen en este mundo.\""}
MultiLanguageSpellData['mx'][239414] = {name = "[q5]Percha de la vigilancia", additional_info = "Hechizo de 2 seg\nComponentes:\nEscamadora primordial , Esencia de fragmento del vacío , Sangre de Sargeras (65), Escama tormentosa (250)\n[q]Crear Percha de vigilancia.\nInstructor de profesión:\nPeletería de Legion (100)\nCosto:\n250\n\n[q5]Percha de vigilancia\nSe liga al equiparlo\nÚnico-Equipado: Legendario de Legion (1)Manos Malla\n7 armadura\n+4 [Agilidad o Intelecto]+6 aguante\n[q2]Aumenta tu índice de celeridad + 3 p.\n[q2]Aumenta tu índice de maestría + 4 p.\n\n[q0]Ranura prismática\n[q0]Ranura prismática\n[q0]Ranura prismática\n\nDurabilidad 70 / 70\nClases: Cazador , Chamán , [Evoker][q2]Equipar: Cada vez que matas a un enemigo, obtienes un 5% de aumento de velocidad de movimiento durante 1 min. Este efecto se acumula hasta 5 veces. Al alcanzar 5 acumulaciones, te convertirás en un búho espiritual cuando estés fuera del combate para aumentar tu velocidad de movimiento aún más y obtener la habilidad de volar.\nNecesitas ser de nivel 40\n[q]\"Incluso en la muerte, los espíritus de los búhos vigilan a sus amos, siempre y cuando tengan un guante firme donde posarse.\""}
MultiLanguageSpellData['mx'][239415] = {name = "[q5]Valor inalterable de Rethu", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nMartillo de héroes olvidados , Esencia de fragmento del vacío , Sangre de Sargeras (65), Barra de acero demoníaco (125)\n[q]Fabricar Valor inalterable de Rethu.\nInstructor de profesión:\nHerrería de Legion (100)\nCosto:\n250\n\n[q5]Valor inalterable de Rethu\nSe liga al equiparlo\nÚnico-Equipado: Legendario de Legion (1)Cintura Placas\n10 armadura\n+4 [Fuerza o Intelecto]+6 aguante\n[q2]Aumenta tu índice de celeridad + 4 p.\n[q2]Aumenta tu índice de maestría + 3 p.\n\n[q0]Ranura prismática\n[q0]Ranura prismática\n[q0]Ranura prismática\n\nDurabilidad 70 / 70\nClases: Guerrero , Paladín , Caballero de la muerte\n[q2]Equipar: Cuando hay un enemigo en un radio de 8 m a tu alrededor, recuperas un 2% de tu salud máxima cada 3 s. Cuando no hay enemigos en un radio de 8 m a tu alrededor, tu velocidad de movimiento aumenta un 15%.\nNecesitas ser de nivel 40\n[q]\"Su valentía era contagiosa.\""}
