MultiLanguageSpellData['mx'][239645] = {name = "Tesoros viles", additional_info = "Instante\n[q]Completar la construcción de la Torre de los Magos te dará acceso a:\n\nDesafíos de artefacto\n El Consejo de los Seis otorga acceso a una serie de desafíos únicos, donde los héroes más dignos pueden poner a prueba su fuerza y habilidad.\n\nCofres de lenguavermis velados\n El poder de la Torre de los magos recorre la Costa Quebrada y deja a la vista los lucrativos Cofres de lenguavermis velados.\n\nRed de portales\n El Kirin Tor otorga acceso a portales que pueden usarse para moverse rápidamente por las Islas Quebradas."}
MultiLanguageSpellData['mx'][239646] = {name = "Abrazo de la Luz", additional_info = "Instante\n[q]Ofrece protección contra el daño."}
MultiLanguageSpellData['mx'][239647] = {name = "Cazador épico", additional_info = "Instante\n[q]Completar la construcción del Disruptor abisal te dará acceso a:\n\nJefes del mundo\n La energía del Disruptor abisal atrae a los enemigos más poderosos a la Costa Quebrada.\n\nPortales abisales inestables\n La activación del Disruptor abisal provoca la aparición de portales abisales inestables por la Costa Quebrada. Actívalos para invocar enemigos peligrosos.\n\nMención del artesano de armaduras\n Los artesanos del nivel más alto recibirán menciones por sus esfuerzos, que les permitirán crear los objetos más legendarios."}
MultiLanguageSpellData['mx'][239648] = {name = "Fuerzas de la orden", additional_info = "Instante\n[q]Completar la construcción del Centro de mando te dará acceso a:\n\nMisiones de mundo de la Catedral\n Con el mando establecido, los esfuerzos pueden concentrarse en atacar la Catedral de la Noche eterna.\n\nRefuerzos de Legión caída\n Los comandantes de Legión caída cuentan con más apoyo en todo el territorio de las Islas Quebradas.\n\nAtaques élite\n Envía campeones dignos a una misión difícil pero lucrativa en el corazón de la Costa Quebrada."}
