MultiLanguageSpellData['mx'][247692] = {name = "Continuo de recuerdos", additional_info = "[q]Tienes una probabilidad mayor de obtener un Cofre de recuerdos de Arenas del tiempo. Los Cofres de recuerdos contienen objetos poderosos que reducen notablemente la dificultad de los desafíos de Cronoportales.\n\nBonificación: Aumenta un 10% la velocidad de movimiento y de montura."}
