MultiLanguageSpellData['mx'][254411] = {name = "Purge", additional_info = "{4% del maná base} {Alcance de 30 m}\nInstante\n[q]Purges the enemy target, removing 1 beneficial Magic effect.[Successfully purging a target grants a stack of Maelstrom Weapon.]"}
MultiLanguageSpellData['mx'][254412] = {name = "Hex", additional_info = "Alcance de 30 mHechizo de 1.7 seg 35 seg de reutilización\n[q]Transforms the enemy into a frog for 1 min. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts."}
MultiLanguageSpellData['mx'][254413] = {name = "Healing Tide Totem", additional_info = "1.12% del maná base\n{Instante} {3 min de reutilización}\n[q]Summons a totem at your feet for 10 s, which pulses every 2 sec, healing all party or raid members within 40 yards for ([350% of Spell Power])."}
