MultiLanguageSpellData['mx'][254416] = {name = "Grounding Totem", additional_info = "1.18% del maná base\n{Instante} {30 seg de reutilización}\n[q]Summons an Air Totem with 5 health at the feet of the caster that will redirect all harmful spells cast on a nearby party or raid member to itself. Will not redirect area of effect spells. Lasts 3 s."}
MultiLanguageSpellData['mx'][254417] = {name = "Earth Shield", additional_info = "{3% del maná base} {Alcance de 40 m}\n{Instante} {6 seg de reutilización}\n[q]Protects the target with an earthen shield, reducing all damage the target receives by 15% and causes the target to be healed for ([112.5% of Spell Power]) when they take an attack equal to 4% of their total health. 4 Charges.\n\n Earth Shield can only be placed on one target at a time.\n(1s de reutilización)"}
MultiLanguageSpellData['mx'][254418] = {name = "Healing Surge", additional_info = "{4% del maná base} {Alcance de 40 m}\nHechizo de 1.5 seg\n[q]A quick surge of healing energy that restores 10 of a friendly target's health."}
MultiLanguageSpellData['mx'][254419] = {name = "Riptide", additional_info = "{1.6% del maná base} {Alcance de 40 m}\n{Instante} {6 seg de reutilización}\n[q]Restorative waters wash over a friendly target, healing them for 5 and an additional 10 over 15 s."}
