MultiLanguageSpellData['mx'][257671] = {name = "Cólera atronadora de Golganneth", additional_info = "Alcance de 100 m\nInstante\n[q]Tus habilidades que infligen daño tienen una probabilidad de crear una Tormenta devastadora en la ubicación de tu objetivo, lo que inflige ( 172 * 6) p. de daño de naturaleza que se dividen entre todos los enemigos en un radio de 6 m durante 6 s.\n\nCólera atronadora de Golganneth\n Si cuentas con la potenciación del Panteón, tus ataques automáticos provocan una ráfaga de rayos que inflige [ 1 * ([Mainhand weapon min base speed]) * 96 ] p. de daño de naturaleza a todos los enemigos en un radio de 8 m alrededor del objetivo. Dura 15 s."}
MultiLanguageSpellData['mx'][257673] = {name = "Energía vital", additional_info = "Instante\n[q]La energía vital de Eonar aumenta a medida que derrotas fuerzas invasoras de la Legión. Cuando su energía vital llegue a 100 atacará al Paraxis y a todas las fuerzas de la Legión con su Fuerza vital.\n\n\nFuerza vital Rango ilimitado Lanzamiento de 3 s Eonar concentra su fuerza vital, golpea al Paraxis y le inflige daño de naturaleza. Además, una ola de choque atraviesa la zona y daña a todos los invasores enemigos."}
MultiLanguageSpellData['mx'][257674] = {name = "Sigilo", additional_info = "{Instante} {2 seg de reutilización}\n[q]Te ocultas en las sombras hasta que lo cancelas. Así, puedes acechar a tus enemigos sin que te detecten.\n\n Mientras estás en sigilo, regeneras un 2 de tu salud cada 1 s."}
MultiLanguageSpellData['mx'][257676] = {name = "Reconstruir", additional_info = "Hechizo de 2.5 seg\n[q]El taumaturgo toma rocas y escombros para rellenar sus grietas y sana un 4% de su salud máxima cada 1 s durante 10 s."}
