MultiLanguageSpellData['mx'][257715] = {name = "Sierra para huesos ceremonial", additional_info = "Hechizo de 2 seg\n[q]A menudo, los drust utilizaban animales en sus rituales, principalmente sus órganos. Las sierras para huesos eran esenciales para romper los costillares de los animales más grandes y arrancarles el corazón."}
MultiLanguageSpellData['mx'][257716] = {name = "Tomo con vínculo rúnico ancestral", additional_info = "Hechizo de 2 seg\n[q]Los drust más fuertes protegían los tomos: su tarea consistía en preservar los encantamientos de sus magias y actuar como conductos para dominar su poder. Algunos eruditos han intentado traducir el idioma antiguo transcrito en estos tomos, pero cuanto más comprendían los escritos, más se hundían en la locura."}
MultiLanguageSpellData['mx'][257717] = {name = "Hoz destripadora", additional_info = "Hechizo de 2 seg\n[q]Se han descubierto muchas de las herramientas que se utilizaban en los rituales de los drust. Una de ellas era una hoz para atravesar el vientre de las víctimas de sus sacrificios y destriparlas. De esta manera, los drust conseguían órganos para sus rituales oscuros."}
MultiLanguageSpellData['mx'][257718] = {name = "Hoja serrada de los drust", additional_info = "Hechizo de 2 seg\n[q]Las hojas de los drust, utilizadas tanto en combate como en ceremonias antiguas, son objetos temibles. Cuando los drust las blanden, estas hojas pueden atravesar cualquier órgano vital en cuestión de segundos."}
MultiLanguageSpellData['mx'][257719] = {name = "Fetiche del ritual", additional_info = "Hechizo de 2 seg\n[q]Cuando los drust aprendían a vincular sus almas con constructos, utilizaban los huesos de sus difuntos como huéspedes. Se dice que, una vez finalizado el ritual, estos fetiches emanaban un resplandor azul tenebroso. Probablemente se trataba de la esencia del alma que manifestaba su poder."}
MultiLanguageSpellData['mx'][257720] = {name = "Vasija de Akun'Jar", additional_info = "Hechizo de 2 seg\n[q]Los zandalari alaban a muchos espíritus divinos poderosos llamados \"loa\". Uno de ellos es el gran truenagarto, Akunda, el loa de las tormentas y los nuevos comienzos. Cree que la tormenta tiene el poder de lavar las penas y el arrepentimiento."}
MultiLanguageSpellData['mx'][257721] = {name = "Urna de óbito", additional_info = "Hechizo de 2 seg\n[q]Durante la época final del Consejo de las tribus, se desató una peste de sangre que mató a miles de trols. Como los cadáveres estaban demasiado corrompidos para darles un sepulcro adecuado, se decidió quemarlos y guardar sus cenizas en urnas especiales. Con el paso del tiempo, este método se convirtió en una práctica común para los zandalari al momento de despedirse de los muertos."}
MultiLanguageSpellData['mx'][257722] = {name = "Ídolo de Rezan", additional_info = "Hechizo de 2 seg\n[q]A lo largo de los años, muchos reyes gobernaron el Imperio zandalari. Sin embargo, todos eran conscientes de la importancia de los poderosos loa y ofrecieron su alabanza al más poderoso de ellos, Rezan. Este loa honra los hechos por encima de las palabras, pero no se toma a bien los deslices y es rencoroso."}
MultiLanguageSpellData['mx'][257723] = {name = "Caperuza de sumo boticario", additional_info = "Hechizo de 2 seg\n[q]Los practicantes de la alquimia entre los zandalari tenían una sociedad exclusiva dentro del imperio conocida como los \"Shadra'Zan\". La entrada a su hermandad incluía un ritual en el que el ingresante debía beber una poción preparada con su propia sangre. Si el ingresante era capaz de tolerar los efectos, se lo consideraba digno y podía aprender los secretos que albergaban."}
MultiLanguageSpellData['mx'][257724] = {name = "Máscara de vudú de Bwonsamdi", additional_info = "Hechizo de 2 seg\n[q]Los zandalari vestían estas máscaras en sus rituales para rezarle al loa de la muerte y honrarlo. Bwonsamdi, a cambio, respondía a sus plegarias o los maldecía con un dolor insoportable, según su estado de ánimo. Bwonsamdi es el protector de los muertos y se lleva los espíritus de todos los que lo veneran a su reino, el \"Otro Lado\"."}
MultiLanguageSpellData['mx'][257730] = {name = "Bendición del clamacielos", additional_info = "Hechizo de 30 seg\n[q]Potencia a los sethrak cercanos con el poder de la tormenta."}
MultiLanguageSpellData['mx'][257731] = {name = "Cruza el velo", additional_info = nil}
MultiLanguageSpellData['mx'][257732] = {name = "Bramido devastador", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 2.75 seg 3 seg de reutilización\n[q]Libera un poderoso aullido, inflige 3927608 p. de daño físico e interrumpe durante 1.5 s el lanzamiento de hechizos."}
MultiLanguageSpellData['mx'][257734] = {name = "Reserva privada de Raoul", additional_info = "Alcance de 100 mHechizo de 1 seg 5 seg de reutilización\n[q]La Reserva privada de Raúl es un brebaje poderoso que inflige 12 p. de daño de naturaleza. Duerme al objetivo durante 10 s cuando se consumen 10 acumulaciones de la Reserva privada de Raúl. El movimiento cancela este efecto."}
MultiLanguageSpellData['mx'][257735] = {name = "Hígado superdotado", additional_info = "Instante\n[q]¡Raúl tiene el hígado mucho más entrenado que tú! Caes en un sueño profundo durante 10 s."}
MultiLanguageSpellData['mx'][257736] = {name = "Borrasca atronadora", additional_info = "Hechizo de 3 seg 4 seg de reutilización\n[q]Canaliza una tormenta eléctrica que inflige 4364009 p. de daño de naturaleza a los enemigos en un radio de 40 m cada 1.5 s durante 3 s."}
