MultiLanguageSpellData['mx'][257777] = {name = "Pincho incapacitante", additional_info = "Alcance de 100 m\nHechizo de 1 seg\n[q]Lanza un pincho improvisado hacia un objetivo que inflige 3960 p. de daño de naturaleza y hace que el objetivo sufra 1485 p. de daño de naturaleza cada 2 s durante 12 s. Este efecto reduce la velocidad de movimiento un 50%."}
