MultiLanguageSpellData['mx'][272118] = {name = "Favor de Gonk", additional_info = "Instante\n[q]Cuando reúnas al menos 2 enemigos en un radio de 10 m, llama a una |t Manada de guerra .\n\n Este efecto no puede producirse más de una vez cada 3 m.\n\n Manada de guerra\n Los hijos de Gonk vendrán a ayudarte.\n(3m de reutilización)"}
MultiLanguageSpellData['mx'][272119] = {name = "Favor de Pa'ku", additional_info = "Instante\n[q]Matar a un objetivo activa |t Viento de Pa'ku .\n\n Este efecto no puede producirse más de una vez cada 1 m.\n\n Viento de Pa'ku\n Aumenta la celeridad un 5% y la velocidad de movimiento un 25% durante 15 s.\n(1m de reutilización)"}
