MultiLanguageSpellData['mx'][272121] = {name = "Favor de Akunda", additional_info = "Instante\n[q]Los ataques y las sanaciones otorgan la probabilidad de lanzar|t Sacrotormenta .\n\n Este efecto no puede ocurrir más de una vez cada 1 m.\n\n Sacrotormenta\n La energía de tu Sacrotormenta se propaga al objetivo y llega en cadena a los objetivos cercanos para sanar a los aliados o dañar a los enemigos.\n(1m de reutilización)"}
MultiLanguageSpellData['mx'][272122] = {name = "Favor de Bwonsamdi", additional_info = "Instante\n[q]Matar a un enemigo otorga la probabilidad de lanzar|t Pacto de Bwonsamdi .\n\n Pacto de Bwonsamdi\n Una maldición que explotará e infligirá daño a todos los enemigos cercanos dentro de 4 s e invocará un Sirviente de Bwonsamdi.\n(Probabilidad de que accione: 50%, 3s de reutilización)"}
MultiLanguageSpellData['mx'][272123] = {name = "Favor de Kimbul", additional_info = "Instante\n[q]Probabilidad de infligir |t Desgarro de Kimbul en los ataques.\n\n Este efecto no puede ocurrir más de una vez cada 1 m.\n\n Desgarro de Kimbul\n Inflige 10 p. de daño físico cada 1 s.\n(1m de reutilización)"}
