MultiLanguageSpellData['mx'][273810] = {name = "Despertar de Xalzaix", additional_info = "Hechizo de 2 seg\n[q]Mythrax canaliza su energía hacia Xalzaix y despierta su arma viviente. La energía generada hace que se formen 2 Esferas del olvido.\n\n Cuando se completa la canalización, Xalzaix entra en erupción, inflige 4701 p. de daño de las sombras y aplica Aniquilación a todos los jugadores."}
MultiLanguageSpellData['mx'][273811] = {name = "Despertar de Xalzaix", additional_info = "Instante\n[q]Mythrax canaliza su energía hacia Xalzaix y despierta su arma viviente. La energía generada hace que se formen 2 Esferas del olvido.\n\n Cuando se completa la canalización, Xalzaix entra en erupción, inflige 4701 p. de daño de las sombras y aplica Aniquilación a todos los jugadores."}
MultiLanguageSpellData['mx'][273812] = {name = "Cerbatana de los sethrak", additional_info = "Hechizo de 2 seg\n[q]Los trols del desierto que adoraban a Sethraliss usaban estas cerbatanas para cazar a sus presas, fueran bestias o trols. El veneno en el que se sumergían los dardos paralizaba a la presa y, en el transcurso de un minuto, la mataba. Para que los niños no se portaran mal, se les susurraba \"La espina de Sethraliss\", tal como se escribió en el poema ancestral: \"Si el joven desafía, muestra furia o maldad, con la espina de Sethraliss su castigo llegará\"."}
