MultiLanguageSpellData['mx'][273845] = {name = "Cadena de relámpagos", additional_info = "Alcance de 30 mHechizo de 2 seg 6 seg de reutilización\n[q]Golpea al enemigo con una Descarga de relámpagos que se extiende a otro enemigo cercano. Afecta a un máximo de 3 objetivos e inflige menos daño de naturaleza a cada objetivo sucesivo."}
MultiLanguageSpellData['mx'][273846] = {name = "Tótem Corriente de sanación", additional_info = "40 maná\nInstante\n[q]Invoca un Tótem Corriente de sanación con 5 p. de salud a los pies del taumaturgo durante 1 min que sana 0 p. a los aliados cercanos cada 2 s."}
MultiLanguageSpellData['mx'][273847] = {name = "Corriente de sanación", additional_info = "Instante\n[q]Invoca un tótem a tus pies durante 15 s que sana ([67.68% of Spell Power]) p. de salud a [ Corrientes impetuosas : dos miembros de grupo o banda heridos / un miembro de grupo o banda herido] en un radio de 40 m cada 2 s.\n\n Si ya conoces [ Tótem de Ráfaga de nubes : Tótem de Ráfaga de nubes / Tótem Corriente de sanación ], en cambio obtienes 1 carga más de [ Tótem de Ráfaga de nubes : Tótem de Ráfaga de nubes / Tótem Corriente de sanación ]."}
MultiLanguageSpellData['mx'][273848] = {name = "Tótem Corriente de sanación", additional_info = "Alcance de 100 m\nInstante\n[q]Sana a un herido del grupo o la banda que esté cerca."}
